insert into public.hso_completion_criteria
(project_key,criterion_key,title,description,required,state,scope_weight,acceptance_rule)
values
('hso','SOURCE_CONNECTORS_AND_AUTHORITY','Source connectors & authority mapping','Notion, GitHub, CI and approved external connectors authenticate with least privilege and preserve source authority.',true,'BUILDING',null,'{"requires":["Notion internal connection","GitHub read access","source authority matrix","freshness SLA"],"acceptance":"All required sources can be read and mapped to an explicit owner and authority role."}'::jsonb),
('hso','INGESTION_IDEMPOTENCY_AND_PROVENANCE','Data ingestion, normalization & provenance','Events and source records are normalized, deduplicated, hashed and traceable to canonical source references.',true,'BUILT_UNVERIFIED',null,'{"requires":["stable external IDs","idempotency keys","source snapshots","event replay test"],"acceptance":"Duplicate/replayed events do not duplicate source records and every normalized row has provenance."}'::jsonb),
('hso','STATE_RECONCILIATION_AND_FRESHNESS','Project state reconciliation & freshness','Conflicting versions, duplicate task IDs, stale sources and mismatched evidence are detected before recommendations.',true,'BUILDING',null,'{"requires":["source snapshot reconciliation","conflict detection","stale-source recovery"],"acceptance":"Tested conflicts and stale inputs suppress strategic recommendations."}'::jsonb),
('hso','DEPENDENCY_RISK_HARD_GATES','Dependency and risk analysis engine','Dependency graph, critical path and risk analysis feed deterministic hard eligibility gates.',true,'BUILT_UNVERIFIED',null,'{"requires":["stable dependency task IDs","dependency verification","risk disposition","exact-head CI binding"],"acceptance":"An ineligible task cannot become the primary action regardless of its priority score."}'::jsonb),
('hso','SINGLE_PRIMARY_STRATEGIC_ACTION','Single primary next-action decision','The decision engine emits one primary next action, supporting actions, blocked actions and pending human decisions.',true,'BUILT_UNVERIFIED',null,'{"requires":["fresh sources","all hard gates","complete six-factor score inputs"],"acceptance":"One primary task is selected only when eligible; otherwise NO_ELIGIBLE_ACTION."}'::jsonb),
('hso','STRUCTURED_PROMPT_COMPILER','Snapshot-bound strategic prompt compiler','A ready-to-execute prompt is generated with Context, Objective, Evidence, Scope, Dependencies, Execution steps, Authorization, Acceptance, Validation, Stop conditions and Reporting.',true,'BUILT_UNVERIFIED',null,'{"requires":["decision run","source snapshots","task and commit identity","approval evidence"],"acceptance":"Prompt schema is complete, reproducible and invalidated by material context changes."}'::jsonb),
('hso','WEIGHTED_VERIFIED_PROGRESS_ANALYTICS','Weighted verified progress & milestone analytics','Progress uses explicit scope weights and verified acceptance evidence; milestone actual is compared with planned baseline.',true,'BUILDING',null,'{"requires":["owner-assigned scope weights","verified evidence","parent milestone IDs","baseline start and expected progress"],"acceptance":"Unweighted work is excluded from denominator and weight coverage is disclosed."}'::jsonb),
('hso','WORKFLOW_EXECUTION_TRACEABILITY','Workflow execution tracker & history','Tasks expose instructions, dependencies, agent, target branch, commit, PR, changed files, CI, acceptance evidence, retries and state history.',true,'BUILDING',null,'{"requires":["work item to execution relation","GitHub exact-head evidence","history event capture"],"acceptance":"Every execution traces to a task, runner and target-system evidence; Completed remains distinct from Verified."}'::jsonb),
('hso','DIAGNOSTICS_AND_ROOT_CAUSE_INTELLIGENCE','Diagnostics, root-cause grouping & change intelligence','Critical and high issues have location, cause state, impact, resolution and verification; repeated failures group by common cause.',true,'BUILT_UNVERIFIED',null,'{"requires":["stable root cause key","issue severity model","change events","recovery verification"],"acceptance":"A common root cause is grouped once with all impacted work items."}'::jsonb),
('hso','MISSION_CONTROL_DASHBOARD','Mission Control operational dashboard','Dashboard exposes verified completion, active work, blockers, critical issues, approvals, milestone health, freshness, primary action, analytics and tracker.',true,'BUILDING',null,'{"requires":["active member auth","RLS read policies","dashboard query and UI tests"],"acceptance":"Displayed metrics reconcile to database and unmeasured states are explicit."}'::jsonb),
('hso','MANUAL_WEBHOOK_SCHEDULED_REFRESH','Manual, webhook and scheduled synchronization','Refresh-and-recompute reads live sources, normalizes, reconciles, computes decisions and refreshes UI; missed events recover by schedule.',true,'BUILDING',null,'{"requires":["Supabase secrets","Notion webhook","GitHub Actions variables","15-minute reconciliation","manual refresh"],"acceptance":"End-to-end test proves each trigger and retry path on actual platforms."}'::jsonb),
('hso','SECURITY_RESILIENCE_AND_FINAL_ACCEPTANCE','Security, reliability, recovery & final acceptance','RLS, least-privilege secrets, webhook HMAC, replay protection, retries, DLQ/recovery, observability, security review and end-to-end acceptance pass.',true,'NOT_BUILT',null,'{"requires":["RLS adversarial tests","secret rotation","webhook replay tests","failure recovery","production acceptance"],"acceptance":"Security and reliability acceptance suite passes with no unresolved critical issues."}'::jsonb)
